create table if not exists room_participants (id uuid primary key default gen_random_uuid(), room_id uuid references classroom_rooms(id) on delete cascade, user_id uuid, role text not null check (role in ('teacher','learner','admin')), joined_at timestamptz default now(), left_at timestamptz, connection_status text not null default 'connected', camera_enabled boolean not null default false, mic_enabled boolean not null default false, created_at timestamptz default now(), updated_at timestamptz default now()); alter table room_participants enable row level security; create index if not exists idx_room_participants_room on room_participants(room_id); create index if not exists idx_room_participants_user on room_participants(user_id);
